// Generated by localize.dev. Every locale is bundled. A page's language is the first segment of
// its URL (/es/about), else en.
import en from '../locales/en.json';
import eu from '../locales/eu.json';

export const defaultLang = 'en';
const dictionaries: Record<string, Record<string, unknown>> = { en, eu };
export const languages = Object.keys(dictionaries);
const RTL = [
  'ae',
  'aeb',
  'ar',
  'arc',
  'arq',
  'ars',
  'ary',
  'arz',
  'bal',
  'bej',
  'bgn',
  'bqi',
  'brh',
  'chg',
  'ckb',
  'dv',
  'fa',
  'gbz',
  'glk',
  'he',
  'jpr',
  'jrb',
  'khw',
  'ks',
  'lad',
  'lah',
  'lrc',
  'mde',
  'mzn',
  'nqo',
  'ota',
  'pal',
  'phn',
  'ps',
  'rhg',
  'sam',
  'sd',
  'sdh',
  'shu',
  'sog',
  'swb',
  'syc',
  'syr',
  'trw',
  'ug',
  'ur',
  'yi',
];

/** The language of a page, from its URL. */
export function getLangFromUrl(url: URL) {
  const [, first] = url.pathname.split('/');
  return first && first in dictionaries ? first : defaultLang;
}

export const dirOf = (lang: string) => (RTL.includes(lang.split('-')[0]) ? 'rtl' : 'ltr');

/** The same page in another language: localizePath('/about', 'es') → '/es/about'. */
export function localizePath(path: string, lang: string) {
  const bare = path.replace(new RegExp(`^/(${languages.join('|')})(?=/|$)`), '') || '/';
  return lang === defaultLang ? bare : `/${lang}${bare === '/' ? '' : bare}`;
}

const lookup = (dict: unknown, key: string): unknown =>
  key
    .split('.')
    .reduce<unknown>(
      (node, k) =>
        node && typeof node === 'object' ? (node as Record<string, unknown>)[k] : undefined,
      dict
    );

const ORDER = ['zero', 'one', 'two', 'few', 'many', 'other'];
/** The ICU plural branch for a count: an exact match (=0), else its category, else other. */
function icuBranch(body: string, count: number, rules: Intl.PluralRules) {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const m = /^\s*(=\d+|zero|one|two|few|many|other)\s*\{/.exec(body.slice(i));
    if (!m) break;
    let depth = 1;
    let j = i + m[0].length;
    for (; j < body.length && depth; j++) depth += body[j] === '{' ? 1 : body[j] === '}' ? -1 : 0;
    branches[m[1]] = body.slice(i + m[0].length, j - 1);
    i = j;
  }
  return branches[`=${count}`] ?? branches[rules.select(count)] ?? branches.other;
}
function format(
  value: string,
  params: Record<string, unknown>,
  count: number | null,
  rules: Intl.PluralRules
) {
  let text = value;
  let icu = false;
  if (count !== null) {
    const plural = /^\{\s*\w+\s*,\s*(plural|selectordinal)\s*,([\s\S]*)\}$/.exec(text.trim());
    if (plural) {
      const by =
        plural[1] === 'selectordinal'
          ? new Intl.PluralRules(rules.resolvedOptions().locale, { type: 'ordinal' })
          : rules;
      text = icuBranch(plural[2], count, by) ?? text;
      icu = true;
    } else if (/(?<!\{')\|(?!'\})/.test(text)) {
      const forms = text.split(/\s*(?<!\{')\|(?!'\})\s*/);
      const cats = ORDER.filter((c) =>
        rules.resolvedOptions().pluralCategories.includes(c as Intl.LDMLPluralRule)
      );
      text = forms[Math.min(Math.max(cats.indexOf(rules.select(count)), 0), forms.length - 1)];
    }
  }
  return text.replace(/\{'([^']*)'\}|\{\{\s*(\w+)\s*\}\}|\{(\w+)\}|#/g, (m, literal, a, b) => {
    if (literal !== undefined) return literal;
    if (m === '#') return icu && count !== null ? String(count) : m;
    const name = a ?? b;
    return name in params ? String(params[name]) : m;
  });
}

/** `t('key', { name })` for a language; with a numeric `count`, the plural form for it. */
export function useTranslations(lang: string) {
  const rules = new Intl.PluralRules(lang);
  const ordinalRules = new Intl.PluralRules(lang, { type: 'ordinal' });
  const find = (key: string) =>
    lookup(dictionaries[lang], key) ?? lookup(dictionaries[defaultLang], key);
  return function t(key: string, params: Record<string, unknown> = {}): string {
    const count = typeof params.count === 'number' ? params.count : null;
    // i18next-style plurals are separate keys: key_one, key_other (ordinals: key_ordinal_one…).
    const ordinal = count !== null && params.ordinal === true;
    const form =
      count === null
        ? null
        : ordinal
          ? `ordinal_${ordinalRules.select(count)}`
          : rules.select(count);
    const value =
      (form !== null
        ? (find(`${key}_${form}`) ?? find(`${key}_${ordinal ? 'ordinal_' : ''}other`))
        : undefined) ?? find(key);
    return typeof value === 'string' ? format(value, params, count, rules) : key;
  };
}
